import 'package:test/test.dart';
import 'package:task_manager/task_manager.dart';

void main() {
  group('addTask', () {
    test('assigns incrementing ids starting at 1', () {
      final m = TaskManager();
      expect(m.addTask('a').id, '1');
      expect(m.addTask('b').id, '2');
      expect(m.addTask('c').id, '3');
    });

    test('sets title, priority, and done=false', () {
      final m = TaskManager();
      final t = m.addTask('a', priority: 5);
      expect(t.title, 'a');
      expect(t.priority, 5);
      expect(t.done, isFalse);
      expect(m.addTask('b').priority, 0);
    });
  });

  group('completeTask', () {
    test('marks the task done', () {
      final m = TaskManager();
      final t = m.addTask('a');
      m.completeTask(t.id);
      expect(t.done, isTrue);
    });

    test('throws ArgumentError for unknown id', () {
      final m = TaskManager();
      expect(() => m.completeTask('nope'), throwsArgumentError);
    });
  });

  group('removeTask', () {
    test('removes the task', () {
      final m = TaskManager();
      final t = m.addTask('a');
      m.addTask('b');
      m.removeTask(t.id);
      expect(m.listTasks().map((e) => e.title), ['b']);
    });

    test('throws ArgumentError for unknown id', () {
      final m = TaskManager();
      expect(() => m.removeTask('nope'), throwsArgumentError);
    });
  });

  group('listTasks', () {
    test('returns tasks in insertion order', () {
      final m = TaskManager();
      m.addTask('a');
      m.addTask('b');
      m.addTask('c');
      expect(m.listTasks().map((e) => e.title), ['a', 'b', 'c']);
    });

    test('filters by done', () {
      final m = TaskManager();
      final a = m.addTask('a');
      final b = m.addTask('b');
      m.completeTask(a.id);
      expect(m.listTasks(done: true).map((e) => e.id), [a.id]);
      expect(m.listTasks(done: false).map((e) => e.id), [b.id]);
    });
  });

  group('sortedByPriority', () {
    test('sorts by priority descending', () {
      final m = TaskManager();
      m.addTask('low', priority: 1);
      m.addTask('high', priority: 9);
      m.addTask('mid', priority: 4);
      expect(m.sortedByPriority().map((e) => e.title), ['high', 'mid', 'low']);
    });

    test('is stable for equal priorities', () {
      final m = TaskManager();
      m.addTask('first', priority: 2);
      m.addTask('second', priority: 2);
      m.addTask('third', priority: 2);
      expect(m.sortedByPriority().map((e) => e.title),
          ['first', 'second', 'third']);
    });

    test('does not mutate insertion order', () {
      final m = TaskManager();
      m.addTask('a', priority: 1);
      m.addTask('b', priority: 9);
      m.sortedByPriority();
      expect(m.listTasks().map((e) => e.title), ['a', 'b']);
    });
  });

  group('toJson / loadJson', () {
    test('serializes in insertion order with all keys', () {
      final m = TaskManager();
      final t = m.addTask('a', priority: 3);
      m.completeTask(t.id);
      expect(m.toJson(), [
        {'id': '1', 'title': 'a', 'priority': 3, 'done': true}
      ]);
    });

    test('loadJson replaces tasks in given order', () {
      final m = TaskManager();
      m.addTask('old');
      m.loadJson([
        {'id': '7', 'title': 'x', 'priority': 1, 'done': true},
        {'id': '3', 'title': 'y', 'priority': 0, 'done': false},
      ]);
      expect(m.listTasks().map((e) => e.title), ['x', 'y']);
      expect(m.listTasks().map((e) => e.id), ['7', '3']);
    });

    test('subsequent addTask ids do not collide with loaded ids', () {
      final m = TaskManager();
      m.loadJson([
        {'id': '5', 'title': 'x', 'priority': 0, 'done': false},
        {'id': '2', 'title': 'y', 'priority': 0, 'done': false},
      ]);
      expect(m.addTask('z').id, '6');
    });

    test('round-trips through toJson', () {
      final m = TaskManager();
      m.addTask('a', priority: 2);
      final data = m.toJson();
      final n = TaskManager();
      n.loadJson(data);
      expect(n.toJson(), data);
    });
  });
}

